package app.lensdrop.transfer;
import android.content.Context;import android.database.Cursor;import org.json.*;import java.nio.file.*;import java.util.*;
public final class WatchLedgerIntegrationTest{
 static int passed=0;static final String S="event-device-test-scope",F="Pictures/Event/";
 interface Check{void run(Fixture f)throws Exception;}
 static final class Fixture implements AutoCloseable{
  final Path dir;QueueDb q;WatchLedger w;Fixture()throws Exception{dir=Files.createTempDirectory("lensdrop-ledger-");open();}
  void open(){q=new QueueDb(new Context(dir.toString()));w=new WatchLedger(q);w.ensure(S,F);}
  void restart(){q.close();open();}
  void baseline(int count){var db=q.getWritableDatabase();db.beginTransaction();try{w.begin(S,F,"library-version-1");for(int i=0;i<count;i++)w.exclude(S,"content://image/old-"+i,123,10);w.finishBaseline(S,count);db.setTransactionSuccessful();}finally{db.endTransaction();}}
  long count(String sql){try(Cursor c=q.getReadableDatabase().rawQuery(sql,null)){c.moveToFirst();return c.getLong(0);}}
  String incoming(String uri,boolean recovered)throws Exception{w.arrival(S,uri,"IMAGE.JPG",120,20,false,recovered);q.getWritableDatabase().execSQL("UPDATE watch_items SET stable_since=0 WHERE uri=?",new Object[]{uri});w.arrival(S,uri,"IMAGE.JPG",120,20,false,recovered);try(Cursor c=q.getReadableDatabase().rawQuery("SELECT id FROM jobs WHERE uri=?",new String[]{uri})){return c.moveToFirst()?c.getString(0):null;}}
  void pool(String kind)throws Exception{w.reserve(S,kind);var a=w.toSync(S);for(int i=0;i<a.length();i++)w.cloudGroup(a.getJSONObject(i).getString("id"),"/p/"+UUID.randomUUID().toString().replace("-",""));}
  String delivery(String job){try(Cursor c=q.getReadableDatabase().rawQuery("SELECT delivery_id FROM jobs WHERE id=?",new String[]{job})){c.moveToFirst();return c.getString(0);}}
  public void close()throws Exception{q.close();try(var files=Files.walk(dir)){for(Path p:files.sorted(Comparator.reverseOrder()).toList())Files.delete(p);}}
 }
 static void eq(Object a,Object b){if(!Objects.equals(a,b))throw new AssertionError(a+" != "+b);}
 static void yes(boolean b){if(!b)throw new AssertionError("Expected true");}
 static void throwsIt(Runnable action){try{action.run();}catch(IllegalStateException e){return;}throw new AssertionError("Expected rejection");}
 static void test(String name,Check action)throws Exception{try(Fixture f=new Fixture()){action.run(f);passed++;System.out.println("PASS "+name);}}
 public static void main(String[] args)throws Exception{
  test("Existing 10,000 accessible identities excluded persistently without jobs",f->{f.baseline(10000);eq(f.count("SELECT count(*) FROM watch_items"),10000L);eq(f.count("SELECT count(*) FROM jobs"),0L);f.restart();yes(f.w.ready(S));eq(f.w.summary(S).optLong("excluded"),10000L);});
  test("Old file edits and repeated notifications remain excluded",f->{f.baseline(2);f.w.arrival(S,"content://image/old-0","old.JPG",999,999,false,false);f.w.arrival(S,"content://image/old-0","old.JPG",999,999,false,false);eq(f.count("SELECT count(*) FROM jobs"),0L);});
  test("Newly arrived old capture timestamp is a candidate, not rejected by date",f->{f.baseline(1);f.incoming("content://image/new",false);eq(f.w.candidates(S,0).length(),1);});
  test("Source needs stable size and completed pending flag before job",f->{f.baseline(0);f.w.arrival(S,"content://image/new","new.JPG",120,1,true,false);f.q.getWritableDatabase().execSQL("UPDATE watch_items SET stable_since=0");f.w.arrival(S,"content://image/new","new.JPG",120,1,true,false);eq(f.count("SELECT count(*) FROM jobs"),0L);f.w.arrival(S,"content://image/new","new.JPG",120,1,false,false);eq(f.count("SELECT count(*) FROM jobs"),1L);});
  test("Repeated discovery produces exactly one job",f->{f.baseline(0);String a=f.incoming("content://image/new",false);eq(a,f.incoming("content://image/new",false));eq(f.count("SELECT count(*) FROM jobs"),1L);});
  test("Failed baseline transaction is rolled back, not marked ready",f->{var db=f.q.getWritableDatabase();db.beginTransaction();try{f.w.begin(S,F,"v");f.w.exclude(S,"content://image/old",1,1);}finally{db.endTransaction();}f.restart();yes(!f.w.ready(S));eq(f.count("SELECT count(*) FROM watch_items"),0L);});
  test("Existing baseline cannot be silently reset",f->{f.baseline(1);throwsIt(()->f.w.begin(S,F,"another"));eq(f.w.version(S),"library-version-1");});
  test("Reopen preserves baseline and discovers missed arrivals as candidates",f->{f.baseline(1);f.restart();f.incoming("content://image/during-outage",true);eq(f.w.candidates(S,0).length(),1);eq(f.w.summary(S).optLong("excluded"),1L);});
  test("Group assignment does not occur by default without operator confirmation",f->{f.baseline(0);f.pool("group");f.w.nextGroup(S);String j=f.incoming("content://image/new",false);eq(f.delivery(j),null);});
  test("Opt-in ordered source binds first observation before a subsequent group change",f->{f.baseline(0);f.pool("group");String first=f.w.nextGroup(S);f.w.auto(S,true);f.w.arrival(S,"content://image/new","new.JPG",120,1,true,false);String second=f.w.nextGroup(S);f.q.getWritableDatabase().execSQL("UPDATE watch_items SET stable_since=0");f.w.arrival(S,"content://image/new","new.JPG",120,1,false,false);try(Cursor c=f.q.getReadableDatabase().rawQuery("SELECT delivery_id FROM jobs",null)){c.moveToFirst();eq(c.getString(0),first);}yes(!first.equals(second));yes(!f.w.automatic(S));});
  test("Recovered arrivals do not use trusted auto assignment",f->{f.baseline(0);f.pool("group");f.w.nextGroup(S);f.w.auto(S,true);String j=f.incoming("content://image/recovered",true);eq(f.delivery(j),null);});
  test("History Show QR changes display only, not receiving group",f->{f.baseline(0);f.pool("group");String a=f.w.nextGroup(S),b=f.w.nextGroup(S);f.w.show(S,a);eq(f.w.shown(S),a);eq(f.w.active(S),b);});
  test("Explicit resume changes receiving group but never old job destinations",f->{f.baseline(0);f.pool("group");String a=f.w.nextGroup(S);String j=f.incoming("content://image/a",false);f.w.select(S,j);String b=f.w.nextGroup(S);f.w.resume(S,a);eq(f.w.active(S),a);eq(f.delivery(j),a);yes(!a.equals(b));});
  test("Undo empty Next restores prior group and retires accidental QR",f->{f.baseline(0);f.pool("group");String a=f.w.nextGroup(S),b=f.w.nextGroup(S);f.w.undo(S);eq(f.w.active(S),a);eq(f.w.group(S,b).getString("state"),"cancel_pending");eq(f.w.nextGroup(S).equals(b),false);});
  test("Undo filled group leaves all assigned jobs in their original group",f->{f.baseline(0);f.pool("group");String a=f.w.nextGroup(S),b=f.w.nextGroup(S);String j=f.incoming("content://image/b",false);f.w.select(S,j);f.w.undo(S);eq(f.w.active(S),a);eq(f.delivery(j),b);eq(f.w.group(S,b).getString("state"),"open");});
  test("Undo sees observed but still-writing source assignment, not only ready jobs",f->{f.baseline(0);f.pool("group");f.w.nextGroup(S);String b=f.w.nextGroup(S);f.w.auto(S,true);f.w.arrival(S,"content://image/b","B.JPG",120,1,true,false);f.w.undo(S);eq(f.w.group(S,b).getString("state"),"open");});
  test("Single selected photo creates one immutable QR; other candidates remain unqueued",f->{f.baseline(0);f.pool("single");f.w.mode(S,"single");String a=f.incoming("content://image/a",false),b=f.incoming("content://image/b",false);String link=f.w.select(S,a);eq(f.delivery(a),link);eq(f.delivery(b),null);eq(f.w.candidates(S,0).length(),1);yes(f.q.due(S)!=null);try{f.w.select(S,a);throw new AssertionError("must reject");}catch(IllegalStateException expected){}eq(f.count("SELECT count(*) FROM guest_groups WHERE state='open'"),1L);});
  test("Mode switch preserves previously assigned group and queued jobs",f->{f.baseline(0);f.pool("group");String g=f.w.nextGroup(S),j=f.incoming("content://image/a",false);f.w.select(S,j);f.w.mode(S,"single");eq(f.delivery(j),g);eq(f.q.due(S).delivery,g);});
  test("History and immutable single selection survive reopen",f->{f.baseline(0);f.pool("single");f.w.mode(S,"single");String id=f.w.select(S,f.incoming("content://image/a",false));String path=f.w.group(S,id).getString("guest_path");f.restart();eq(f.w.shown(S),id);eq(f.w.group(S,id).getString("guest_path"),path);eq(f.w.history(S,0).length(),1);});
  test("Changed imported file is flagged, not a fresh candidate or replacement QR",f->{f.baseline(0);String id=f.incoming("content://image/a",false);f.w.arrival(S,"content://image/a","A.JPG",999,888,false,false);eq(f.count("SELECT count(*) FROM jobs"),1L);eq(f.w.summary(S).optLong("changed_sources"),1L);yes(id!=null);});
  test("Pending and unselected candidates prevent a misleading completed wrapup",f->{f.baseline(0);f.incoming("content://image/a",false);eq(f.q.snapshot(S).getJSONObject("production").getLong("candidates"),1L);eq(f.q.due(S),null);});
  test("Prepared QR pool remains bounded, and cancelled QR cannot be shown",f->{f.baseline(0);f.pool("group");f.pool("group");eq(f.count("SELECT count(*) FROM guest_groups"),3L);f.w.nextGroup(S);String b=f.w.nextGroup(S);f.w.undo(S);try{f.w.show(S,b);throw new AssertionError("must reject");}catch(IllegalStateException expected){}});
  test("H2 queue migration keeps legacy jobs while adding separate baseline and delivery fields",f->{f.baseline(0);f.q.add(S,"content://legacy","legacy.JPG",10,1);var db=f.q.getWritableDatabase();db.execSQL("DROP TABLE watch_items");db.execSQL("DROP TABLE watch_sessions");db.execSQL("DROP TABLE guest_groups");db.execSQL("DROP INDEX job_delivery");db.execSQL("ALTER TABLE jobs DROP COLUMN delivery_id");db.execSQL("PRAGMA user_version=2");f.restart();eq(f.count("SELECT count(*) FROM jobs"),1L);eq(f.q.due(S).delivery,null);yes(!f.w.ready(S));});
  test("Explicit skip preserves originals/identity and does not upload unselected files",f->{f.baseline(0);String j=f.incoming("content://image/a",false);f.w.skip(S,j);eq(f.q.snapshot(S).getJSONObject("production").getLong("skipped"),1L);eq(f.q.due(S),null);f.incoming("content://image/a",false);eq(f.w.candidates(S,0).length(),0);yes(!f.q.hasOtherPending("another-scope"));});
  System.out.println("RESULT: "+passed+" exact WatchLedger/QueueDb JVM + SQLite bridge tests passed.");
  System.out.println("Not an Android SDK build, Android instrumentation test, ContentResolver test, or hardware validation.");
 }
}
